INSERT INTO public.diagnostic_tests (id, subject_id, program_id, title, description, diagnostic_type, duration_minutes, source_name, is_public, pcs_key)
VALUES ('a1000000-0000-4000-8000-000000000026', '8ee8190d-fd18-4a08-916a-7f8258c3cd7e', '24e65170-ad2c-47d7-9a79-45b15726cc55',
 'Диагностика ЕГЭ — Русский язык, 11 класс',
 'Входная диагностика по всем 26 заданиям ЕГЭ. Короткий ответ, автопроверка, результат сразу обновляет карту знаний.',
 'entry', 90, 'Pathy', true, 'ege_ru_diag_26')
ON CONFLICT (id) DO UPDATE SET is_public = true, title = EXCLUDED.title, subject_id = EXCLUDED.subject_id, program_id = EXCLUDED.program_id;

WITH src(n, prompt, ans) AS (
  VALUES
  (1, 'Самостоятельно подберите подчинительный союз, который должен стоять на месте пропуска: «Учёные считают, ... язык постоянно меняется».', 'что'),
  (2, 'Из предложения «Эти изменения происходят медленно, поэтому носители языка их почти не замечают» выпишите сочинительный союз.', 'поэтому'),
  (3, 'Укажите номер лексического значения слова ЯЗЫК в предложении «Русский язык — сложная система знаков»: 1) орган в полости рта; 2) система знаков для общения; 3) пленный; 4) стержень в колоколе. Ответ дайте цифрой.', '2'),
  (4, 'В одном из слов допущена ошибка в постановке ударения. Выпишите это слово: дОговор, слИвовый, красИвее, тОрты.', 'договор'),
  (5, 'Заменив неверно употреблённое слово паронимом, выпишите подобранное слово: «Он надел пальто и ОДЕЛ шапку».', 'надел'),
  (6, 'Отредактируйте предложение: исправьте лексическую ошибку, исключив лишнее слово. Выпишите это слово: «Он вернулся обратно домой поздно вечером».', 'обратно'),
  (7, 'В одном из слов допущена ошибка в образовании формы слова. Выпишите это слово правильно: более лучший, пять килограммов, поезжай, их дом.', 'лучший'),
  (8, 'Определите вид грамматической ошибки в предложении «Приехав в город, мне понравился парк»: нарушение в построении предложения с деепричастным ... . Впишите пропущенное слово.', 'оборотом'),
  (9, 'Укажите пропущенную букву, одинаковую для всех слов: р..стение, изл..гать, к..сательная.', 'а'),
  (10, 'Укажите пропущенную букву, одинаковую для всех слов: пр..бывать в город (приехать), пр..градить, пр..красный.', 'и'),
  (11, 'Укажите пропущенную букву, одинаковую для всех слов: раскле..вать, доверч..вый, отзывч..вый.', 'и'),
  (12, 'Выпишите слово, в котором на месте пропуска пишется буква Я: кле..щий, дыш..щий, слыш..щий.', 'клеящий'),
  (13, 'Определите слово, которое с НЕ пишется слитно, и выпишите его: (не)решена, (не)вероятный, (не)кто иной.', 'невероятный'),
  (14, 'Выпишите слово, которое пишется слитно: (в)течение дня, (не)смотря на дождь, (по)этому мосту.', 'несмотря'),
  (15, 'Сколько букв Н пишется на месте пропуска в слове «кова..ый»? Ответ дайте цифрой.', '1'),
  (16, 'Укажите номер предложения, в котором нужно поставить ОДНУ запятую: 1) Ветер стих и море успокоилось. 2) Дождь и ветер. Ответ дайте цифрой.', '1'),
  (17, 'Сколько запятых нужно поставить в предложении «Мальчик читая книгу забыл о времени»? Ответ дайте цифрой.', '2'),
  (18, 'Сколько запятых нужно поставить в предложении «Я думаю что он конечно придёт»? Ответ дайте цифрой.', '2'),
  (19, 'Сколько запятых нужно поставить в предложении «Дом который стоял на холме был виден издалека»? Ответ дайте цифрой.', '2'),
  (20, 'Сколько запятых нужно поставить в предложении «Когда рассвело мы вышли в путь и дорога показалась короче»? Ответ дайте цифрой.', '2'),
  (21, 'Тире в предложении «Чтение — лучшее учение» ставится между подлежащим и ... . Впишите пропущенное слово.', 'сказуемым'),
  (22, 'Какое утверждение соответствует содержанию текста? 1) Язык не меняется. 2) Изменения языка почти незаметны для носителей. Ответ дайте цифрой.', '2'),
  (23, 'Какой тип речи представлен во фрагменте, где автор доказывает свою мысль и приводит аргументы? Ответ дайте одним словом.', 'рассуждение'),
  (24, 'Из предложения «Язык живёт и дышит вместе с людьми» выпишите название использованного средства выразительности (одним словом).', 'метафора'),
  (25, 'Среди предложений 4–6 найдите то, которое связано с предыдущим при помощи личного местоимения. Укажите номер предложения цифрой.', '5'),
  (26, 'Приём, при котором однородные члены расположены по возрастанию значимости, называется ... . Впишите одно слово.', 'градация')
), ins AS (
  INSERT INTO public.tasks (subject_id, program_id, task_key, prompt, answer_type, options, correct_answer, difficulty, task_type, exam_task_number, is_published, source_name)
  SELECT '8ee8190d-fd18-4a08-916a-7f8258c3cd7e', '24e65170-ad2c-47d7-9a79-45b15726cc55',
         'ege_ru_diag_26_' || n, prompt, 'text', '[]'::jsonb, to_jsonb(ans), 'medium', 'short_answer', n, true, 'Pathy'
  FROM src
  ON CONFLICT (task_key) DO UPDATE SET prompt = EXCLUDED.prompt, correct_answer = EXCLUDED.correct_answer,
    exam_task_number = EXCLUDED.exam_task_number, is_published = true,
    subject_id = EXCLUDED.subject_id, program_id = EXCLUDED.program_id, answer_type = 'text'
  RETURNING id, exam_task_number
)
INSERT INTO public.diagnostic_test_tasks (diagnostic_test_id, task_id, order_index, points)
SELECT 'a1000000-0000-4000-8000-000000000026', id, exam_task_number, 1 FROM ins
ON CONFLICT DO NOTHING;